VALUES
('Caterpillar','388-7286','پمپ انتقال سوخت CAT 388-7286','Cat Fuel Transfer Pump with external involute spline gear. Cat lists C18 Marine among compatible model families; public listing does not establish serial/arrangement-specific fitment.',ARRAY['C18'],'سیستم سوخت‌رسانی - پمپ انتقال سوخت','Cat Parts Store','https://parts.cat.com/en/catcorp/product/388-7286','Official Cat listing: Fuel Transfer Pump with external involute spline gear; length 6.3 in, height 4.5 in, gray (flake) iron; MARINE ENGINE C18 / C18 MARINE listed. Family-level evidence only.','NEEDS_SERIAL_CHECK',false,now(),'{"length_in":6.3,"height_in":4.5,"material":"Gray (Flake) Iron","gear_type":"External Involute Spline"}'::jsonb,ARRAY['C18','C18 MARINE'],'UNVERIFIED','Cat lists C18 Marine at model-family level; verify full engine serial number and arrangement in Cat SIS.','https://parts.cat.com/en/catcorp/product/388-7286'),
('Caterpillar','239-9349','مجموعه لوله فیلتر سوخت CAT 239-9349','Cat Fuel Filter Tube Assembly conducts pressurized fuel from the fuel manifold to the filter. Cat lists C18 Marine among compatible model families; exact serial effectivity is not supplied in the public listing.',ARRAY['C18'],'سیستم سوخت‌رسانی - لوله فیلتر سوخت','Cat Parts Store','https://parts.cat.com/en/catcorp/product/239-9349','Official Cat listing: alloy mixed-metal fuel filter tube assembly; withstands 240 kPa; compatible models include MARINE ENGINE C18. Family-level evidence only.','NEEDS_SERIAL_CHECK',false,now(),'{"material":"Alloy Mixed Metal","fuel_pressure_kpa":240,"component_type":"Fuel Filter Tube Assembly"}'::jsonb,ARRAY['C18'],'UNVERIFIED','Cat lists MARINE ENGINE C18 at model-family level; verify full engine serial number and arrangement in Cat SIS.','https://parts.cat.com/en/catcorp/product/239-9349'),
('Caterpillar','20R-1527','پمپ انتقال سوخت بازسازی‌شده CAT 20R-1527','Cat Reman Fuel Transfer Pump (A), alternative to 388-7286. Cat lists C18 Marine among compatible model families; reman status and core terms must be checked with dealer, and exact serial effectivity remains unverified.',ARRAY['C18'],'سیستم سوخت‌رسانی - پمپ انتقال سوخت بازسازی‌شده','Cat Parts Store','https://parts.cat.com/en/catcorp/product/20R-1527','Official Cat listing: Cat Reman Fuel Transfer Pump (A), 6.3 in length x 4.5 in height; compatible models include MARINE ENGINE C18; compare alternate 388-7286. Family-level evidence only.','NEEDS_SERIAL_CHECK',false,now(),'{"length_in":6.3,"height_in":4.5,"condition":"REMAN","alternate_for":"388-7286"}'::jsonb,ARRAY['C18'],'UNVERIFIED','Cat lists MARINE ENGINE C18 at model-family level; verify full engine serial number, arrangement, reman/core terms in Cat SIS/dealer.','https://parts.cat.com/en/catcorp/product/20R-1527'),
('Caterpillar','20R-1525','پمپ انتقال سوخت بازسازی‌شده CAT 20R-1525','Cat Reman Fuel Transfer Pump. Cat lists C18 Marine and 3406E among compatible marine engine families; exact serial/arrangement applicability remains unverified.',ARRAY['C18','3406E'],'سیستم سوخت‌رسانی - پمپ انتقال سوخت بازسازی‌شده','Cat Parts Store','https://parts.cat.com/en/catcorp/product/20R-1525','Official Cat listing: Cat Reman Fuel Transfer Pump; compatible models include MARINE ENGINE C18, C15 and 3406E. Family-level evidence only; check reman/core terms with dealer.','NEEDS_SERIAL_CHECK',false,now(),'{"condition":"REMAN","component_type":"Fuel Transfer Pump"}'::jsonb,ARRAY['C18','C15','3406E'],'UNVERIFIED','Cat lists MARINE ENGINE C18 at model-family level; verify full engine serial number and arrangement in Cat SIS.','https://parts.cat.com/en/catcorp/product/20R-1525'),
('Caterpillar','384-8612','پمپ انتقال سوخت CAT 384-8612','Cat Fuel Transfer Pump. Cat lists C18 and 3406E marine engine families among compatible models; exact serial/arrangement applicability is not established.',ARRAY['C18','3406E'],'سیستم سوخت‌رسانی - پمپ انتقال سوخت','Cat Parts Store','https://parts.cat.com/en/catcorp/product/384-8612','Official Cat listing: Fuel Transfer Pump; compatible models include MARINE ENGINE C18, C15 and 3406E. Also appears as a component in Cat fuel transfer pump kit 448-4451. Family-level evidence only.','NEEDS_SERIAL_CHECK',false,now(),'{"component_type":"Fuel Transfer Pump","kit_reference":"448-4451"}'::jsonb,ARRAY['C18','C15','3406E'],'UNVERIFIED','Cat lists MARINE ENGINE C18 at model-family level; verify full engine serial number and arrangement in Cat SIS.','https://parts.cat.com/en/catcorp/product/384-8612')
ON CONFLICT (part_number) DO UPDATE SET
 name=EXCLUDED.name,description=EXCLUDED.description,engine_models=EXCLUDED.engine_models,technical_group=EXCLUDED.technical_group,
 source_name=EXCLUDED.source_name,source_url=EXCLUDED.source_url,source_note=concat_ws(E'\n',nullif(public.part_catalog.source_note,''),EXCLUDED.source_note),
 verification_status='NEEDS_SERIAL_CHECK',is_active=false,source_accessed_at=now(),specifications=public.part_catalog.specifications || EXCLUDED.specifications,
 compatible_models=EXCLUDED.compatible_models,application_type='UNVERIFIED',application_evidence=EXCLUDED.application_evidence,
 application_source_url=EXCLUDED.application_source_url,updated_at=now();

UPDATE public.part_catalog
SET name=CASE part_number WHEN '6N-6259' THEN 'پایه فیلتر سوخت CAT 6N-6259' WHEN '6N-6252' THEN 'شیر فیلتر سوخت CAT 6N-6252' WHEN '1N-3789' THEN 'پایه فیلتر سوخت CAT 1N-3789' ELSE name END,
    description=CASE part_number
      WHEN '6N-6259' THEN 'Cat Fuel Filter Base, spin-on type, alloy aluminum with adhesive/sealant. Cat compatible-model listing includes C18 Marine among multiple marine engines.'
      WHEN '6N-6252' THEN 'Cat Fuel Filter Valve, carbon steel, used to regulate fuel flow and provide filtration-unit shutoff. Cat compatible-model listing includes C18 Marine among multiple marine engines.'
      WHEN '1N-3789' THEN 'Cat Fuel Filter Base, spin-on type. Official Cat compatible-model listing includes C18 Marine and C18 among multiple engine families.'
      ELSE description END,
    source_name='Cat Parts Store',source_url='https://parts.cat.com/en/catcorp/product/'||part_number,
    verification_status='NEEDS_SERIAL_CHECK',application_type='UNVERIFIED',is_active=false,
    application_evidence=concat_ws(E'\n',nullif(application_evidence,''),'Cat Parts Store lists C18 Marine at model-family level; exact serial number and arrangement verification in Cat SIS is required.'),
    application_source_url='https://parts.cat.com/en/catcorp/product/'||part_number,
    source_note=concat_ws(E'\n',nullif(source_note,''),'Provenance updated to official Cat Parts Store listing; family-level C18 Marine reference only, not serial-confirmed.'),
    source_accessed_at=now(),updated_at=now()
WHERE part_number IN ('6N-6259','6N-6252','1N-3789');

UPDATE public.products p
SET status='INACTIVE',application_type='UNVERIFIED',
    application_evidence=concat_ws(E'\n',nullif(p.application_evidence,''),'C18 Marine family-level Cat reference only; verify exact engine serial and arrangement before sale.'),
    updated_at=now()
WHERE regexp_replace(upper(p.sku),'[^A-Z0-9]','','g') IN ('3887286','2399349','20R1527','20R1525','3848612','6N6259','6N6252','1N3789');